message.content:
{"events": [
{"key": "fy_club_inventory", "story": "타이가는 부실의 상자를 손가락으로 세다가 목록을 다시 편다. 한 상자에는 가져온 사람의 이름이 없다. 시로는 먼저 학생들에게 물어보자고 한다.", "intro": "누락된 상자의 주인을 찾을지, 다른 구역의 확인을 도울지 결정한다.", "choices": [
{"label": "기록용품을 사서 타이가와 빠진 이름을 확인한다", "result": "기록용품을 준비해 타이가와 함께 명단을 대조했다. 빠진 이름의 대상을 좁혀가며 확인하는 법을 익혔다. 아직 확인되지 않은 상자들은 그대로 부실에 남겨두었다."},
{"label": "시로와 넓은 길목의 확인까지 맡는다", "result": "시로와 함께 더 넓은 길목을 맡기로 하고 이동 경로를 확보했다. 시로의 분석에 따라 이동 범위를 넓혔으나, 상자의 주인은 여전히 미궁이다."},
{"label": "확인된 물건만 정리하고 보수와 보급을 받는다", "result": "정리가 끝난 물건들만 분류하여 보수와 물약을 챙겼다. 상자의 주인에 대한 조사는 미뤄둔 채 다음 업무를 준비했다."}
]},
{"key": "fy_regular_contact", "story": "린이 빈 연락 기록을 시로 앞에 놓는다. 시로는 다른 사람의 일을 돕다 잊었다고 한다. 세이버는 확인할 곳을 나누면 될지 묻는다.", "intro": "연락 누락지를 분류할지, 세이버와 방어 자세를 맞출지 선택한다.", "choices": [
{"label": "기록용품을 마련하고 린과 확인할 순서를 나눈다", "result": "기록용품을 마련해 린과 연락 우선순위를 정리했다. 효율적인 확인 절차를 익혔지만, 아직 닿지 않은 곳은 목록에 남았다."},
{"label": "세이버와 맡을 길목을 줄이고 기본 자세를 맞춘다", "result": "세이버와 협력하여 맡을 길목을 좁히고 기본 방어 자세를 점검했다. 방어적 태세는 갖췄으나 빈 연락 기록은 해결되지 않았다."},
{"label": "연락이 닿은 곳만 정리해 보수와 물약을 받는다", "result": "연락이 확인된 부분만 정리하여 보수와 물약을 수령했다. 나머지 누락된 연락처들은 그대로 방치되었다."}
]},
{"key": "fy_신지_offer", "story": "신지는 자신이 라이더의 마스터라는 말을 먼저 꺼내고 협력을 제안한다. 린은 원하는 조건이 빠져 있다고 지적한다. 시로는 받아들일지보다 먼저 무엇을 확인할지 망설인다.", "intro": "제안의 근거를 찾을지, 아처와 요구사항을 파악할지 결정한다.", "choices": [
{"label": "연락 비용을 내고 더 넓은 구역에서 제안의 근거를 찾는다", "result": "비용을 들여 더 넓은 구역을 수색하며 신지의 주장을 검증했다. 제안의 기초를 다졌으나 협력 조건은 아직 불투명하다."},
{"label": "준비물을 마련하고 아처와 상대가 원하는 것을 짚는다", "result": "준비물을 챙겨 아처와 함께 상대의 의중을 파악했다. 아처의 시선으로 요구사항을 분석했으나 신지의 제안은 수락되지 않았다."},
{"label": "확인된 문장만 따로 적고 조사 보수를 받는다", "result": "확인된 문구만 갈무리하여 조사 보수를 챙겼다. 신지의 제안에 대한 검토는 일단 중단했다."}
]},
{"key": "fy_vantage_map", "story": "아처가 지도에 들어갈 길과 돌아설 자리를 다른 표시로 그린다. 시로는 표시 밖의 사람들을 가리킨다. 둘은 네가 어느 길목을 맡을지 기다린다.", "intro": "아처와 큰 상대를 살필지, 시로와 위험한 곳을 맡을지 선택한다.", "choices": [
{"label": "지도와 표시 도구를 마련해 아처와 큰 상대를 살핀다", "result": "지도와 도구를 챙겨 아처와 함께 주변의 위협적인 요소를 파악했다. 전반적인 상황 파악을 마쳤으나 표시 밖의 인물들은 여전히 미확인 상태다."},
{"label": "시로와 더 위험한 길목을 맡을 준비를 한다", "result": "시로와 협력해 가장 위험한 구역으로 향할 채비를 마쳤다. 더 강한 적과 마주할 가능성이 높아졌으나 지도의 빈틈은 그대로다."},
{"label": "돌아갈 길을 한 곳 줄이고 보급품을 챙긴다", "result": "퇴로를 단순화하고 보급품을 확보했다. 이동은 수월해졌지만 아처가 그은 지도의 세부 사항은 챙기지 못했다."}
]},
{"key": "fy_pause_outside", "story": "린이 오늘은 잠깐 바깥을 둘러보자고 한다. 세이버는 낯선 길에서 자꾸 주위를 살피고 시로의 걸음이 앞서간다. 준비할 물건과 걸을 범위를 골라야 한다.", "intro": "세이버와 보폭을 맞출지, 린과 기록을 정리할지 결정한다.", "choices": [
{"label": "외출 준비물을 사고 세이버와 걸을 간격을 맞춘다", "result": "준비물을 구입하고 세이버와 보폭을 맞춰 걷기 시작했다. 동행의 안정성은 확보했으나 린이 제안한 바깥의 정보는 아직 수집되지 않았다."},
{"label": "린과 다음 연락에 필요한 기록을 정리한다", "result": "린과 협력하여 다음 연락을 위한 기초 자료를 정리했다. 체계적인 준비를 마쳤으나 세이버와 함께 밖을 둘러보는 일은 미뤄졌다."},
{"label": "멀리 나가지 않고 보급 정리를 도와 보수를 받는다", "result": "보급품을 정리하며 보수를 챙기는 것으로 외출을 갈음했다. 린의 제안은 거절되었고 밖의 상황은 알 수 없게 되었다."}
]},
{"key": "fy_teacher_statement", "story": "잇세이의 진술에는 직접 본 일과 들은 일이 같은 줄에 적혀 있다. 린은 어느 말이 어느 쪽인지 다시 묻고 싶어 한다. 시로는 같은 학교 선생님이라는 이유만으로 결론 내릴 수 없다고 말한다.", "intro": "더 넓은 구역을 확인해 사실을 파악할지, 시로와 구조를 살필지 선택한다.", "choices": [
{"label": "조사 비용을 내고 더 넓은 길목에서 빠진 사실을 확인한다", "result": "비용을 들여 더 넓은 구역을 훑으며 잇세이 진술의 빈틈을 메웠다. 일부 사실을 보완했으나 여전히 모호한 부분은 기록에 남았다."},
{"label": "시로와 확인된 구조만 다시 살핀다", "result": "시로와 함께 현재 확인된 구조적 정보들만 다시 검토했다. 논리적 정합성을 높였지만 새로운 사실은 드러나지 않았다."},
{"label": "빈칸을 그대로 남기고 기록 보수를 받는다", "result": "진술의 빈칸을 그대로 둔 채 기록 보수를 수령했다. 추가적인 조사 없이 현재의 자료로 업무를 마쳤다."}
]},
{"key": "fy_two_ideals", "story": "시로와 아처는 다음 싸움에서 무엇을 먼저 맡을지 다르게 생각한다. 시로는 놓치게 될 사람을, 아처는 감당할 결과를 짚는다. 누구에게 맞추더라도 둘의 의견 차이는 남는다.", "intro": "시로의 뜻에 따라 강한 상대를 맡을지, 아처의 뜻에 따라 전장의 부담을 나눌지 결정한다.", "choices": [
{"label": "시로와 더 강한 상대를 맡을 각오를 준비한다", "result": "시로의 의견을 따라 더 강력한 적을 상대할 준비를 마쳤다. 전방의 위협은 인지했으나 아처가 우려하는 결과에 대한 대비는 부족하다."},
{"label": "표시 도구를 마련하고 아처와 큰 전장의 부담을 나눈다", "result": "아처와 협력해 전장의 전반적인 부담을 분산시키는 표시를 마쳤다. 전략적 배분은 끝났으나 시로가 걱정하는 인명 피해 가능성은 여전하다."},
{"label": "둘의 주장을 따로 적고 보급 정리 일을 돕는다", "result": "두 사람의 의견 차이를 기록으로 남기고 보급 정리 업무를 수행했다. 갈등은 중재하지 못한 채 자료만 정리되었다."}
]}
]
}
